#!/usr/bin/env node
/**
 * SyncOut patch v6.4 — run from the repo root:   node syncout-patch-v6.4.js
 * Works from v6.2 (what's on GitHub), v6.3 or v6.3.1. Includes both.
 *
 * Booking
 *   • promo codes at checkout, and links like /events/x?promo=RIYA10 that apply themselves
 *   • early-bird prices: crossed-out "was" price, badge, live countdown, scheduled sale windows
 *   • waitlist on sold-out tickets
 *   • split passes: each friend gets their own QR and can arrive separately
 * Door
 *   • /door app for staff with phone + PIN (scan and check in only)
 *   • per-guest check-in ("2 of 4 in"); a used QR can't be used again
 * Admin
 *   • Sales dashboard, Promo codes, Waitlist (notify everyone), Door staff
 * Ops
 *   • the database upgrades itself during every build — no more "Set up database" clicks
 */
"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execSync } = require("child_process");

const DRY = process.argv.includes("--dry");
const NO_INSTALL = process.argv.includes("--no-install");
const BACKUP = path.join(".patch-backups", "v6.4");

if (!fs.existsSync("src/components/motion/Reveal.tsx")) {
  console.error("\n  Apply v6, v6.1 and v6.2 first (your repo should already have them), then this one.\n");
  process.exit(1);
}

if (!fs.existsSync("package.json")) {
  console.error("\n  Run this from the repo root (no package.json here).\n");
  process.exit(1);
}
try {
  const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
  if (pkg.name !== "syncout") {
    console.error("\n  This is the '" + pkg.name + "' repo, not syncout.\n");
    process.exit(1);
  }
} catch {
  console.error("\n  package.json could not be read.\n");
  process.exit(1);
}

